import { ParameterValue, Tool, Command } from "@/components/commandly/types/tool";
import { writeClipboard } from "@/components/commandly/utils/clipboard";
import { generateCommand, getToolFlagForms } from "@/components/commandly/utils/generate-command";
import { Button } from "@/components/ui/button";
import { CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { cn } from "@/lib/utils";
import { TerminalIcon, CopyIcon, SaveIcon } from "lucide-react";
import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import { toast } from "sonner";

interface GeneratedCommandProps {
  tool: Tool;
  selectedCommand?: Command | null;
  parameterValues: Record<string, ParameterValue>;
  onSaveCommand?: (command: string) => void;
  /** Position emitted by default: 0 is a parameter's full flag, later positions its aliases. */
  defaultFlagFormIndex?: number;
  children?: ReactNode;
}

interface FlagFormOption {
  index: number;
  label: string;
}

interface GeneratedCommandContextValue {
  generatedCommand: string;
  flagFormIndex: number;
  setFlagFormIndex: (value: number) => void;
  flagFormOptions: FlagFormOption[];
  onCopyCommand: () => void;
  onSaveCommand?: (command: string) => void;
}

const GeneratedCommandContext = createContext<GeneratedCommandContextValue | null>(null);

function useGeneratedCommandContext() {
  const context = useContext(GeneratedCommandContext);

  if (!context) {
    throw new Error("GeneratedCommand compound components must be used within GeneratedCommand.");
  }

  return context;
}

function GeneratedCommandRoot({
  tool,
  selectedCommand: providedCommand,
  parameterValues,
  onSaveCommand,
  defaultFlagFormIndex = 0,
  children,
}: GeneratedCommandProps) {
  const [flagFormIndex, setFlagFormIndex] = useState(defaultFlagFormIndex);

  const flagFormOptions = useMemo<FlagFormOption[]>(
    () => getToolFlagForms(tool).map((label, index) => ({ index, label })),
    [tool],
  );

  const generatedCommand = useMemo(
    () =>
      generateCommand(tool, parameterValues, {
        selectedCommand: providedCommand,
        flagFormIndex,
      }),
    [tool, parameterValues, providedCommand, flagFormIndex],
  );

  const copyCommand = useCallback(() => {
    writeClipboard(generatedCommand).then(
      () => toast("Command copied!"),
      () => toast.error("Copy failed"),
    );
  }, [generatedCommand]);

  const contextValue = useMemo(
    () => ({
      generatedCommand,
      flagFormIndex,
      setFlagFormIndex,
      flagFormOptions,
      onCopyCommand: copyCommand,
      onSaveCommand,
    }),
    [generatedCommand, flagFormIndex, flagFormOptions, copyCommand, onSaveCommand],
  );

  return (
    <GeneratedCommandContext.Provider value={contextValue}>
      {generatedCommand ? (
        (children ?? (
          <div className="min-w-0 space-y-4">
            <GeneratedCommandOutput />
            <GeneratedCommandActions />
          </div>
        ))
      ) : (
        <GeneratedCommandEmptyState />
      )}
    </GeneratedCommandContext.Provider>
  );
}

function GeneratedCommandToolbar({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      className={cn("flex flex-wrap items-center justify-end gap-2", className)}
      {...props}
    />
  );
}

function GeneratedCommandHeader({
  children,
  className,
  ...props
}: ComponentProps<typeof CardHeader>) {
  return (
    <CardHeader
      className={cn("flex flex-row items-center justify-between gap-3 space-y-0", className)}
      {...props}
    >
      <CardTitle className="flex items-center gap-2">
        <TerminalIcon className="h-5 w-5" />
        Generated Command
      </CardTitle>
      {children}
    </CardHeader>
  );
}

function GeneratedCommandFlagFormPreference({
  className,
  ...props
}: Omit<ComponentProps<typeof SelectTrigger>, "value" | "onValueChange">) {
  const { flagFormIndex, setFlagFormIndex, flagFormOptions } = useGeneratedCommandContext();

  if (flagFormOptions.length < 2) return null;

  return (
    <div className="flex shrink-0 items-center gap-2">
      <Label className="font-mono text-xs tracking-[0.12em] text-muted-foreground uppercase">
        Flag style
      </Label>
      <Select
        value={String(flagFormIndex)}
        onValueChange={(value) => setFlagFormIndex(Number(value))}
      >
        <SelectTrigger
          className={cn("h-8 w-36", className)}
          aria-label="Flag style"
          {...props}
        >
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {flagFormOptions.map((option) => (
            <SelectItem
              key={option.index}
              value={String(option.index)}
            >
              {option.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </div>
  );
}

function GeneratedCommandOutput({ className, ...props }: ComponentProps<"div">) {
  const { generatedCommand } = useGeneratedCommandContext();

  return (
    <div
      className={cn("overflow-x-auto rounded bg-muted p-4 font-mono text-sm", className)}
      {...props}
    >
      <div className="min-w-max whitespace-nowrap">{generatedCommand}</div>
    </div>
  );
}

function GeneratedCommandActions({ className, ...props }: ComponentProps<"div">) {
  const { generatedCommand, onCopyCommand, onSaveCommand } = useGeneratedCommandContext();

  return (
    <div
      className={cn("flex flex-col gap-2 sm:flex-row", className)}
      {...props}
    >
      <Button
        onClick={onCopyCommand}
        variant="outline"
        className="w-full sm:flex-1"
      >
        <CopyIcon className="mr-2 h-4 w-4" />
        Copy Command
      </Button>
      {onSaveCommand && (
        <Button
          onClick={() => onSaveCommand(generatedCommand)}
          variant="outline"
          className="w-full sm:flex-1"
        >
          <SaveIcon className="mr-2 h-4 w-4" />
          Save Command
        </Button>
      )}
    </div>
  );
}

function GeneratedCommandEmptyState() {
  return (
    <div className="py-8 text-center">
      <TerminalIcon className="mx-auto mb-4 h-12 w-12 text-muted-foreground" />
      <p className="text-muted-foreground">Configure parameters to generate the command.</p>
    </div>
  );
}

export const GeneratedCommand = Object.assign(GeneratedCommandRoot, {
  Header: GeneratedCommandHeader,
  Toolbar: GeneratedCommandToolbar,
  FlagFormPreference: GeneratedCommandFlagFormPreference,
  Output: GeneratedCommandOutput,
  Actions: GeneratedCommandActions,
  EmptyState: GeneratedCommandEmptyState,
});

export interface ToolInfo {
  /** A brief human-readable description of what the tool does. */
  description?: string;
  /** The version string of the tool (e.g. "1.0.0"). */
  version?: string;
  /** The homepage or documentation URL for the tool. */
  url?: string;
}

export interface Command {
  /** Unique identifier for this command within the tool. */
  key: string;
  /** Human-readable display name of the command. */
  displayName: string;
  /** Alternate spellings that invoke this command in place of its name. */
  aliases?: string[];
  /** Brief description of what this command does. */
  description?: string;
  /** Whether this command opens an interactive session or prompt. */
  interactive?: boolean;
  /** Display sort position relative to sibling commands. */
  sortOrder?: number;
  /** Parameters accepted by this command. Keys are unique among them. Omit for grouping commands. */
  parameters?: Parameter[];
  /** Groups of this command's parameters with mutual exclusion or required-one-of constraints. */
  exclusionGroups?: ExclusionGroup[];
  /** Subcommands nested beneath this command. */
  commands?: Command[];
}

export type InstallationMethod = "package_manager" | "binary" | "docker" | "script";

export interface InstallationSource {
  /** Unique identifier for this installation source within the tool. */
  key: string;
  /** How the tool is installed. */
  method: InstallationMethod;
  /** Package manager name, set only when method is "package_manager" (e.g. "brew", "go"). */
  manager?: string;
  /** The command that installs the tool. */
  command: string;
  /** Documentation URL describing this installation method. */
  url?: string;
  /** Platforms this installation method applies to. */
  os?: Array<"linux" | "macos" | "windows">;
  /** Additional context for this installation source. */
  note?: string;
}

export interface Installation {
  /** The list of documented ways to install the tool. */
  sources: InstallationSource[];
}

export interface InstallationMethodOption {
  method: InstallationMethod;
  /** Human-readable label for the method. */
  label: string;
}

/** The methods in presentation order; a new method must be given a position here. */
export const INSTALLATION_METHODS: InstallationMethodOption[] = [
  { method: "package_manager", label: "Package manager" },
  { method: "binary", label: "Release binary" },
  { method: "docker", label: "Docker" },
  { method: "script", label: "Script" },
];

export interface ParameterEnumValue {
  /** The raw value passed to the CLI for this choice. */
  value: string;
  /** Human-readable label shown to the user for this enum choice. */
  displayName: string;
  /** Description of what this enum value does or represents. */
  description?: string;
  /** Whether this is the default selection when no value is provided. */
  isDefault?: boolean;
  /** Display sort position relative to sibling enum values. */
  sortOrder?: number;
}

export interface ParameterEnumValues {
  /** The list of allowed enum choices. */
  values: ParameterEnumValue[];
  /** Whether the user can select multiple values at once. */
  allowMultiple?: boolean;
  /** Separator character used when joining multiple selected values. */
  separator?: string;
}

export type ParameterValidationType =
  | "min_length"
  | "max_length"
  | "min_value"
  | "max_value"
  | "regex";

export interface ParameterValidation {
  /** Unique identifier for this validation rule. */
  key: string;
  /** The type of validation to apply. */
  validationType: ParameterValidationType;
  /** The value to validate against (e.g. the max length number, or a regex pattern). */
  validationValue: string;
  /** The error message to display when validation fails. */
  errorMessage: string;
}

export type ParameterDependencyType = "requires" | "conflicts_with";

export interface ParameterDependency {
  /** Unique identifier for this dependency rule. */
  key: string;
  /** Key of the parameter that owns this dependency. */
  parameterKey: string;
  /** Key of the parameter this dependency references. */
  dependsOnParameterKey: string;
  /** Whether this parameter requires or conflicts with the referenced parameter. */
  dependencyType: ParameterDependencyType;
  /** Optional value that the referenced parameter must have for this dependency to apply. */
  conditionValue?: string;
}

export type ParameterValue = string | number | boolean | string[];

// eslint-disable-next-line @typescript-eslint/no-empty-object-type
export interface ToolMetadata {}

// eslint-disable-next-line @typescript-eslint/no-empty-object-type
export interface ParameterMetadata {
  /** Arbitrary tags for categorising or filtering parameters. */
  tags?: string[];
}

export type ParameterType = "Flag" | "Option" | "Argument";

export type ParameterDataType = "String" | "Number" | "Boolean" | "Enum";

export interface Parameter {
  /** Unique identifier among its command's parameters. For flags and options this is the full flag, dashes included (e.g. "--output", "-list"). */
  key: string;
  /** Human-readable display name of the parameter. */
  displayName: string;
  /** Brief description of what this parameter does or accepts. */
  description?: string;
  /** Optional grouping label for organising related parameters in the UI. */
  group?: string;
  /** Additional metadata such as tags. */
  metadata?: ParameterMetadata;
  /** Whether this is a boolean flag, a key-value option, or a positional argument. */
  parameterType: ParameterType;
  /** The data type of the parameter's value. */
  dataType: ParameterDataType;
  /** Whether the user must provide this parameter. */
  isRequired?: boolean;
  /** Whether this parameter can be specified multiple times. */
  isRepeatable?: boolean;
  /** Short names and other alternate invocation forms (e.g. ["-o"]). The full flag is `key`. */
  aliases?: string[];
  /** Whether this parameter is also accessible from the subcommands of its command, recursively. */
  recursive?: boolean;
  /** Zero-based position index for positional arguments. */
  position?: number;
  /** Display sort position relative to sibling parameters. */
  sortOrder?: number;
  /** Separator character used when the option accepts multiple values in one argument (e.g. ","). */
  arraySeparator?: string;
  /** Separator between key and value for key=value style options (e.g. "="). */
  keyValueSeparator?: string;
  /** Allowed enum choices when dataType is "Enum". */
  enum?: ParameterEnumValues;
  /** Validation rules applied to this parameter's value. */
  validations?: ParameterValidation[];
  /** Dependencies on other parameters (requires or conflicts-with relationships). */
  dependencies?: ParameterDependency[];
}

export type ExclusionType = "mutual_exclusive" | "required_one_of";

export interface ExclusionGroup {
  /** Unique identifier for this exclusion group. */
  key?: string;
  /** Human-readable name for this exclusion group. */
  displayName: string;
  /** Whether parameters in this group are mutually exclusive or one is required. */
  exclusionType: ExclusionType;
  /** Keys of the parameters that participate in this exclusion group. */
  parameterKeys: string[];
}

export interface Tool {
  /** Unique binary name for the tool that it can be invoked from the command line (e.g. "httpx"). */
  binaryName: string;
  /** Human-readable display name for the tool (e.g. "HTTPx"). */
  displayName: string;
  /** Whether the root tool invocation opens an interactive session or prompt. */
  interactive?: boolean;
  /** General information about the tool such as description, version, and URL. */
  info?: ToolInfo;
  /** Structured installation instructions for the tool. */
  installation?: Installation;
  /**
   * Parameters accepted by the tool itself, before a command is chosen. A tool's own flags live
   * here; do not model the root invocation as a command named after the binary, or the root would
   * be described twice.
   */
  parameters: Parameter[];
  /** List of all commands and subcommands defined for this tool. */
  commands: Command[];
  /** Groups of the tool's own parameters with mutual exclusion or required-one-of constraints. */
  exclusionGroups?: ExclusionGroup[];
  /** Arbitrary metadata attached to the tool. */
  metadata?: ToolMetadata;
}

import type {
  Command,
  ExclusionGroup,
  Parameter,
  ParameterValue,
  Tool,
} from "@/components/commandly/types/tool";

export const slugify = (text: string): string => {
  return text
    .toString()
    .toLowerCase()
    .trim()
    .replace(/\s+/g, "-") // Replace spaces with -
    .replace(/[^\w-]+/g, "") // Remove all non-word chars
    .replace(/--+/g, "-") // Replace multiple - with single -
    .replace(/^-+/, "") // Trim - from start of text
    .replace(/-+$/, ""); // Trim - from end of text
};

const flattenCommands = (commands: Command[], sink: Command[] = []): Command[] => {
  for (const command of commands) {
    sink.push(command);
    if (command.commands?.length) flattenCommands(command.commands, sink);
  }
  return sink;
};

/** Every command in the tool, depth-first, each parent before its children. */
export const getAllCommands = (tool: Tool): Command[] => flattenCommands(tool.commands ?? []);

/** Every command beneath `command`, depth-first. */
export const getAllSubcommands = (command: Command): Command[] =>
  flattenCommands(command.commands ?? []);

/** The command with this key anywhere in the tree. */
export const findCommand = (tool: Tool, key: string): Command | undefined =>
  getAllCommands(tool).find((command) => command.key === key);

/**
 * The command to show when the caller has not chosen one: the command named after the binary when
 * there is one, otherwise the first command in the tree.
 */
export const getDefaultCommand = (tool: Tool): Command | null => {
  const commands = getAllCommands(tool);
  return (
    commands.find(
      (command) => command.displayName.toLowerCase() === tool.binaryName.toLowerCase(),
    ) ??
    commands[0] ??
    null
  );
};

/** The chain of commands from the outermost ancestor down to the one with this key. */
export const getCommandChain = (tool: Tool, key: string): Command[] => {
  const walk = (commands: Command[], path: Command[]): Command[] | null => {
    for (const command of commands) {
      const next = [...path, command];
      if (command.key === key) return next;
      const found = walk(command.commands ?? [], next);
      if (found) return found;
    }
    return null;
  };
  return walk(tool.commands ?? [], []) ?? [];
};

export const getCommandPath = (command: Command, tool: Tool): string => {
  const chain = getCommandChain(tool, command.key);
  if (chain.length === 0) return command.displayName;
  return chain.map((step) => step.displayName).join(" ");
};

/**
 * A recursive parameter is inherited: it belongs to its command and to every command below it.
 * Root-scoped, it is inherited by the whole tree.
 */
export const isInheritedParameter = (param: Parameter): boolean => param.recursive === true;

/**
 * Resolves the parameters that apply to the currently selected command: its own parameters,
 * plus those inherited from its ancestors via `recursive`, outermost ancestor first.
 */
export const resolveApplicableParameters = (
  tool: Tool,
  selectedCommand?: Command | null,
): Parameter[] => {
  const rootParameters = tool.parameters ?? [];

  if (!selectedCommand) return rootParameters;

  // Tool-level recursive parameters are inherited by every command in the tree.
  const resolved: Parameter[] = rootParameters.filter(isInheritedParameter);
  const chain = getCommandChain(tool, selectedCommand.key);

  for (const command of chain) {
    for (const parameter of command.parameters ?? []) {
      if (command.key === selectedCommand.key || parameter.recursive) {
        resolved.push(parameter);
      }
    }
  }

  return resolved;
};

/** The parameters declared directly on a command, or on the root invocation when `commandKey` is null. */
export const getCommandParameters = (tool: Tool, commandKey: string | null): Parameter[] => {
  if (commandKey === null) return tool.parameters ?? [];
  return findCommand(tool, commandKey)?.parameters ?? [];
};

/** The exclusion groups declared directly on a command, or on the root invocation when `commandKey` is null. */
export const getExclusionGroups = (tool: Tool, commandKey: string | null): ExclusionGroup[] => {
  if (commandKey === null) return tool.exclusionGroups ?? [];
  return findCommand(tool, commandKey)?.exclusionGroups ?? [];
};

/** Every exclusion group in the tool, root invocation first, in command order. */
export const getAllExclusionGroups = (tool: Tool): ExclusionGroup[] =>
  (tool.exclusionGroups ?? []).concat(
    getAllCommands(tool).flatMap((command) => command.exclusionGroups ?? []),
  );

/** Whether a parameter's current value counts as provided. */
export const hasParameterValue = (value: ParameterValue | undefined): boolean =>
  value !== undefined &&
  value !== "" &&
  value !== false &&
  !(Array.isArray(value) && value.every((entry) => entry === ""));

/**
 * The exclusion groups that constrain a selection: those with at least one member among the
 * parameters that apply to `selectedCommand`.
 */
export const resolveExclusionGroups = (
  tool: Tool,
  selectedCommand?: Command | null,
): ExclusionGroup[] => {
  const applicable = new Set(resolveApplicableParameters(tool, selectedCommand).map((p) => p.key));
  return getAllExclusionGroups(tool).filter((group) =>
    group.parameterKeys.some((key) => applicable.has(key)),
  );
};

/**
 * The parameters a mutually exclusive group rules out, keyed by parameter, given what is
 * provided. Its members are alternatives to one another, so once one is provided every other
 * member is ruled out; the first provided member of each group keeps its place.
 */
export const excludedParameters = (
  groups: ExclusionGroup[],
  values: Record<string, ParameterValue>,
): Map<string, ExclusionGroup> => {
  const excluded = new Map<string, ExclusionGroup>();
  for (const group of groups) {
    if (group.exclusionType !== "mutual_exclusive") continue;
    const [provided] = group.parameterKeys.filter((key) => hasParameterValue(values[key]));
    if (provided === undefined) continue;
    for (const key of group.parameterKeys) {
      if (key !== provided) excluded.set(key, group);
    }
  }
  return excluded;
};

/** The parameters a `required_one_of` group makes mandatory, while none of its members is provided. */
export const requiredParameterKeys = (
  groups: ExclusionGroup[],
  values: Record<string, ParameterValue>,
): Set<string> => {
  const required = new Set<string>();
  for (const group of groups) {
    if (group.exclusionType !== "required_one_of") continue;
    if (group.parameterKeys.some((key) => hasParameterValue(values[key]))) continue;
    for (const key of group.parameterKeys) required.add(key);
  }
  return required;
};

/** Every parameter in the tool, root invocation first, in command order. */
export const getAllParameters = (tool: Tool): Parameter[] =>
  (tool.parameters ?? []).concat(
    getAllCommands(tool).flatMap((command) => command.parameters ?? []),
  );

/**
 * Rewrites a command tree bottom-up, handing `transform` each command with its children already
 * mapped. Walks that drop commands need their own traversal, since this one is one-to-one.
 */
export const mapCommandTree = (
  commands: Command[],
  transform: (command: Command) => Command,
): Command[] =>
  commands.map((command) =>
    transform(
      command.commands?.length
        ? { ...command, commands: mapCommandTree(command.commands, transform) }
        : command,
    ),
  );

/** Applies `update` to the command with `key` anywhere in the tree, leaving every other command alone. */
export const updateCommand = (
  tool: Tool,
  key: string,
  update: (command: Command) => Command,
): Tool => ({
  ...tool,
  commands: mapCommandTree(tool.commands ?? [], (command) =>
    command.key === key ? update(command) : command,
  ),
});

/** Drops the command with `key` and everything nested beneath it. */
export const removeCommand = (tool: Tool, key: string): Tool => ({
  ...tool,
  commands: dropCommand(tool.commands ?? [], key),
});

const dropCommand = (commands: Command[], key: string): Command[] =>
  commands
    .filter((command) => command.key !== key)
    .map((command) =>
      command.commands?.length
        ? { ...command, commands: dropCommand(command.commands, key) }
        : command,
    );

/**
 * Applies `update` to the parameters an owner declares: the command with `ownerKey`, or the tool's
 * own parameters when it is null. `recursive` decides where a parameter *applies*, never where it
 * is written, so this deliberately does not touch inherited parameters.
 */
export const updateParameters = (
  tool: Tool,
  ownerKey: string | null,
  update: (parameters: Parameter[]) => Parameter[],
): Tool =>
  ownerKey === null
    ? { ...tool, parameters: update(tool.parameters ?? []) }
    : updateCommand(tool, ownerKey, (command) => ({
        ...command,
        parameters: update(command.parameters ?? []),
      }));

/** Same as {@link updateParameters} for the exclusion groups an owner declares. */
export const updateExclusionGroups = (
  tool: Tool,
  ownerKey: string | null,
  update: (groups: ExclusionGroup[]) => ExclusionGroup[],
): Tool =>
  ownerKey === null
    ? { ...tool, exclusionGroups: update(tool.exclusionGroups ?? []) }
    : updateCommand(tool, ownerKey, (command) => ({
        ...command,
        exclusionGroups: update(command.exclusionGroups ?? []),
      }));

/** Drops the parameter with `key` from the set an owner declares. */
export const removeParameter = (tool: Tool, ownerKey: string | null, key: string): Tool =>
  updateParameters(tool, ownerKey, (parameters) =>
    parameters.filter((parameter) => parameter.key !== key),
  );

/** Reorders `items` so the given keys take those positions, stamping each item's `sortOrder`. */
export const reorderByKeys = <T extends { key: string; sortOrder?: number }>(
  items: T[],
  keys: string[],
): T[] => {
  const slots: number[] = [];
  const byKey = new Map<string, T>();
  const reordered = new Set(keys);

  items.forEach((item, index) => {
    byKey.set(item.key, item);
    if (reordered.has(item.key)) slots.push(index);
  });

  const next = [...items];
  keys.forEach((key, sortOrder) => {
    const slot = slots[sortOrder];
    const item = byKey.get(key);
    if (slot !== undefined && item) next[slot] = { ...item, sortOrder };
  });
  return next;
};

import type { Command, Parameter, ParameterValue, Tool } from "@/components/commandly/types/tool";
import {
  excludedParameters,
  getAllParameters,
  getCommandPath,
  getDefaultCommand,
  hasParameterValue,
  resolveApplicableParameters,
  resolveExclusionGroups,
} from "@/components/commandly/utils/tool";

export interface GenerateCommandOptions {
  selectedCommand?: Command | null;
  /** Index into a parameter's flag forms to emit; falls back to the canonical form. */
  flagFormIndex?: number;
}

/**
 * The full flag for a parameter. For `Flag` and `Option` types this is the key itself, which
 * carries its own dashes (e.g. "--output", "-list"). Positional arguments have no flag.
 */
export const getCanonicalFlag = (param: Parameter): string => param.key;

/** Every form that invokes a parameter: the full flag first, then its short and other names. */
export const getFlagForms = (param: Parameter): string[] => {
  if (param.parameterType === "Argument") return [];
  const forms = [param.key, ...(param.aliases ?? [])];
  return forms.filter((form, index) => forms.indexOf(form) === index);
};

/** The highest number of flag forms any parameter offers: its canonical flag plus its aliases. */
export const getFlagFormCount = (tool: Tool): number =>
  getAllParameters(tool).reduce((max, param) => Math.max(max, getFlagForms(param).length), 0);

/** Labels for the flag positions: position 0 is the parameter's own key, the rest are its aliases. */
const FLAG_FORM_LABELS = ["Full name", "Short name"];

/** One label per flag position any parameter of the tool offers. */
export const getToolFlagForms = (tool: Tool): string[] =>
  Array.from(
    { length: getFlagFormCount(tool) },
    (_, index) => FLAG_FORM_LABELS[index] ?? `Alternate ${index}`,
  );

export function generateCommand(
  tool: Tool,
  parameterValues: Record<string, ParameterValue>,
  options: GenerateCommandOptions = {},
): string {
  const hasCommands = tool.commands.length > 0;
  const selectedCommand =
    options.selectedCommand === undefined ? getDefaultCommand(tool) : options.selectedCommand;
  const flagFormIndex = options.flagFormIndex ?? 0;

  let command = tool.binaryName;

  if (hasCommands && selectedCommand) {
    const commandPath = getCommandPath(selectedCommand, tool);
    if (tool.binaryName !== commandPath) {
      command = `${tool.binaryName} ${commandPath}`;
    }
  }

  const excluded = excludedParameters(
    resolveExclusionGroups(tool, selectedCommand),
    parameterValues,
  );

  const parametersWithValues = resolveApplicableParameters(tool, selectedCommand)
    .filter((param) => !excluded.has(param.key))
    .map((param) => ({ param, value: parameterValues[param.key] }))
    .filter(({ value }) => hasParameterValue(value));

  const positionalParams = parametersWithValues
    .filter(({ param }) => param.parameterType === "Argument")
    .sort((a, b) => (a.param.position || 0) - (b.param.position || 0));

  parametersWithValues.forEach(({ param, value }) => {
    if (param.parameterType === "Flag") {
      const flag = getFlagForms(param)[flagFormIndex] ?? getCanonicalFlag(param);
      if (value === true) {
        command += ` ${flag}`;
      } else if (param.isRepeatable && typeof value === "number" && value > 0) {
        command += ` ${flag}`.repeat(value);
      }
      return;
    }

    if (param.parameterType === "Option") {
      const flag = getFlagForms(param)[flagFormIndex] ?? getCanonicalFlag(param);

      const separator = param.keyValueSeparator ?? " ";
      if (Array.isArray(value)) {
        const entries = value.filter((entry) => entry !== "");
        if (entries.length === 0) return;

        if (param.arraySeparator) {
          command += ` ${flag}${separator}${entries.join(param.arraySeparator)}`;
          return;
        }

        entries.forEach((entry) => {
          command += ` ${flag}${separator}${entry}`;
        });
        return;
      }

      command += ` ${flag}${separator}${value}`;
    }
  });

  positionalParams.forEach(({ value }) => {
    if (!Array.isArray(value)) {
      command += ` ${value}`;
    }
  });

  return command;
}

/** Writes `text` to the clipboard, rejecting when the browser refuses access. */
export async function writeClipboard(text: string): Promise<void> {
  if (!navigator.clipboard) throw new Error("Clipboard unavailable");
  await navigator.clipboard.writeText(text);
}
